// friday13.cs — Friday the 13th experiments with the proleptic Gregorian calendar

// Find the earliest Friday the 13th starting from 0001-01-01
var date = new DateOnly(1, 1, 13); // start checking the 13th of each month
DateOnly? earliest = null;

while (date.Year == 1)
{
    if (date.DayOfWeek == DayOfWeek.Friday)
    {
        earliest = date;
        break;
    }
    date = date.AddMonths(1);
}

// If not found in year 1, keep going
if (earliest is null)
{
    date = new DateOnly(2, 1, 13);
    while (true)
    {
        if (date.DayOfWeek == DayOfWeek.Friday)
        {
            earliest = date;
            break;
        }
        date = date.AddMonths(1);
    }
}

Console.WriteLine($"Earliest Friday the 13th: {earliest:yyyy-MM-dd}");
Console.WriteLine();

// Count Friday the 13ths in a full 400-year cycle (the Gregorian calendar repeats every 400 years)
int count = 0;
var countByMonth = new int[12];

for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        var d = new DateOnly(year, month, 13);
        if (d.DayOfWeek == DayOfWeek.Friday)
        {
            count++;
            countByMonth[month - 1]++;
        }
    }
}

Console.WriteLine($"Friday the 13ths in a 400-year cycle: {count}");
Console.WriteLine();
Console.WriteLine("Breakdown by month:");
for (int i = 0; i < 12; i++)
{
    Console.WriteLine($"  {new DateOnly(2000, i + 1, 1):MMMM,-12} {countByMonth[i]}");
}
Console.WriteLine();
Console.WriteLine($"Average per year: {count / 400.0:F4}");

